    45→pub fn get_custody_groups(
    46→    raw_node_id: [u8; 32],
    47→    custody_group_count: u64,
    48→    config: &Config,
    49→) -> Result<HashSet<CustodyIndex>> {
    50→    let number_of_custody_groups = config.number_of_custody_groups;
    51→    ensure!(
    52→        custody_group_count <= number_of_custody_groups,
    53→        Error::InvalidCustodyGroupCount {
    54→            custody_group_count,
    55→            number_of_custody_groups,
    56→        },
    57→    );
    58→
    59→    // Skip computation for super node
    60→    if custody_group_count == number_of_custody_groups {
    61→        return Ok((0..number_of_custody_groups).collect::<HashSet<_>>());
    62→    }
    63→
    64→    let mut current_id = NodeId::from_be_bytes(raw_node_id);
    65→
    66→    let mut custody_groups = BTreeSet::new();
    67→    while (custody_groups.len() as u64) < custody_group_count {
    68→        let mut hasher = Sha256::new();
    69→        let mut bytes = [0u8; 32];
    70→
    71→        current_id.into_raw().to_little_endian(&mut bytes);
    72→
    73→        hasher.update(bytes);
    74→        bytes = hasher.finalize().into();
    75→
    76→        let output_prefix = [
    77→            bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6], bytes[7],
    78→        ];
    79→
    80→        let output_prefix_u64 = u64::from_le_bytes(output_prefix);
    81→        let custody_group = output_prefix_u64
    82→            .checked_rem(number_of_custody_groups)
    83→            .expect("number of custody groups must not be zero");
    84→        custody_groups.insert(custody_group);
    85→
    86→        if current_id == Uint256::MAX {
    87→            // > Overflow prevention
    88→            current_id = Uint256::ZERO;
    89→        } else {
    90→            current_id = current_id + Uint256::one();
    91→        }
    92→    }
    93→
    94→    Ok(custody_groups.into_iter().collect())
    95→}
    96→
    97→pub fn compute_columns_for_custody_group<P: Preset>(
    98→    custody_group: CustodyIndex,
    99→    config: &Config,
   100→) -> Result<impl Iterator<Item = ColumnIndex>> {
   101→    let number_of_custody_groups = config.number_of_custody_groups;
   102→    ensure!(
   103→        custody_group < number_of_custody_groups,
   104→        Error::InvalidCustodyGroup {
   105→            custody_group,
   106→            number_of_custody_groups,
   107→        },
   108→    );
   109→
   110→    let mut columns = Vec::new();
   111→    for i in 0..config.columns_per_group::<P>() {
   112→        columns.push(ColumnIndex::from(
   113→            number_of_custody_groups * i + custody_group,
   114→        ));
   115→    }
   116→
   117→    Ok(columns.into_iter())
   118→}
   119→
   120→pub fn compute_subnets_from_custody_group<P: Preset>(
   121→    custody_group: CustodyIndex,
   122→    config: &Config,
   123→) -> Result<impl Iterator<Item = SubnetId> + '_> {
   124→    let subnets = compute_columns_for_custody_group::<P>(custody_group, config)?
   125→        .map(|column_index| misc::compute_subnet_for_data_column_sidecar(config, column_index))
   126→        .unique();
   127→
   128→    Ok(subnets)
   129→}
   130→
   131→pub fn compute_subnets_for_node<P: Preset>(
   132→    raw_node_id: [u8; 32],
   133→    custody_group_count: u64,
   134→    config: &Config,
   135→) -> Result<HashSet<SubnetId>> {
   136→    let mut subnets = HashSet::new();
   137→    for custody_group in get_custody_groups(raw_node_id, custody_group_count, config)? {
   138→        let custody_group_subnets = compute_subnets_from_custody_group::<P>(custody_group, config)?;
   139→
   140→        subnets.extend(custody_group_subnets);
   141→    }
   142→
   143→    Ok(subnets)
   144→}
   145→
   146→/// Verify if the data column sidecar is valid.
   147→pub fn verify_data_column_sidecar<P: Preset>(data_column_sidecar: &DataColumnSidecar<P>) -> bool {
   148→    let DataColumnSidecar {
   149→        index,
   150→        column,
   151→        kzg_commitments,
   152→        kzg_proofs,
   153→        ..
   154→    } = data_column_sidecar;
   155→
   156→    // The sidecar index must be within the valid range
   157→    if *index >= P::NumberOfColumns::U64 {
   158→        return false;
   159→    }
   160→
   161→    // A sidecar for zero blobs is invalid
   162→    if kzg_commitments.is_empty() {
   163→        return false;
   164→    }
   165→
   166→    // The column length must be equal to the number of commitments/proofs
   167→    if column.len() != kzg_commitments.len() || column.len() != kzg_proofs.len() {
   168→        return false;
   169→    }
   170→
   171→    true
   172→}
   173→
   174→/// Verify if the KZG proofs are correct.
   175→pub fn verify_kzg_proofs<P: Preset>(
   176→    data_column_sidecar: &DataColumnSidecar<P>,
   177→    backend: KzgBackend,
   178→    metrics: Option<&Arc<Metrics>>,
   179→) -> Result<bool> {
   180→    let _timer = metrics.as_ref().map(|metrics| {
   181→        metrics
   182→            .data_column_sidecar_kzg_verification_batch
   183→            .start_timer()
   184→    });
   185→
   186→    let DataColumnSidecar {
   187→        index,
   188→        column,
   189→        kzg_commitments,
   190→        kzg_proofs,
   191→        ..
   192→    } = data_column_sidecar;
   193→
   194→    let cell_indices: Vec<u64> = vec![*index; column.len()];
   195→
   196→    verify_cell_kzg_proof_batch::<P>(kzg_commitments, cell_indices, column, kzg_proofs, backend)
   197→}
   198→
   199→pub fn verify_sidecar_inclusion_proof<P: Preset>(
   200→    data_column_sidecar: &DataColumnSidecar<P>,
   201→    metrics: Option<&Arc<Metrics>>,
   202→) -> bool {
   203→    let _timer = metrics.as_ref().map(|metrics| {
   204→        metrics
   205→            .data_column_sidecar_inclusion_proof_verification
   206→            .start_timer()
   207→    });
   208→
   209→    let DataColumnSidecar {
   210→        kzg_commitments,
   211→        signed_block_header,
   212→        kzg_commitments_inclusion_proof,
   213→        ..
   214→    } = data_column_sidecar;
   215→
   216→    // Fields in BeaconBlockBody before blob KZG commitments
   217→    let index_at_commitment_depth = 11;
   218→
   219→    // is_valid_blob_sidecar_inclusion_proof
   220→    is_valid_merkle_branch(
   221→        kzg_commitments.hash_tree_root(),
   222→        *kzg_commitments_inclusion_proof,
   223→        index_at_commitment_depth,
   224→        signed_block_header.message.body_root,
   225→    )
   226→}
   227→
   228→pub fn recover_matrix<P: Preset>(
   229→    partial_matrix: &[MatrixEntry<P>],
   230→    backend: KzgBackend,
   231→) -> Result<Vec<MatrixEntry<P>>> {
   232→    let mut partial_matrix_map = BTreeMap::new();
   233→    for matrix in partial_matrix {
   234→        partial_matrix_map
   235→            .entry(matrix.row_index)
   236→            .or_insert(Vec::new())
   237→            .push(matrix);
   238→    }
   239→
   240→    partial_matrix_map
   241→        .into_par_iter()
   242→        .map(|(_, entries)| {
   243→            let (cell_indices, cells): (Vec<_>, Vec<_>) =
   244→                entries.iter().map(|e| (e.column_index, &e.cell)).unzip();
   245→
   246→            recover_cells_and_kzg_proofs::<P>(cell_indices, cells, backend)
   247→        })
   248→        .collect::<Result<Vec<_>>>()
   249→        .map(construct_full_matrix)
   250→}
   251→
   252→fn get_data_column_sidecars<P: Preset>(
   253→    signed_block_header: SignedBeaconBlockHeader,
   254→    kzg_commitments: &ContiguousList<KzgCommitment, P::MaxBlobCommitmentsPerBlock>,
   255→    kzg_commitments_inclusion_proof: BlobCommitmentsInclusionProof<P>,
   256→    cells_and_kzg_proofs: &[CellsAndKzgProofs<P>],
   257→) -> Result<Vec<Arc<DataColumnSidecar<P>>>> {
   258→    let blob_count = kzg_commitments.len();
   259→    ensure!(
   260→        cells_and_kzg_proofs.len() == blob_count,
   261→        Error::BlobCommitmentsLengthMismatch {
   262→            blob_count,
   263→            commitments_length: kzg_commitments.len(),
   264→        }
   265→    );
   266→
   267→    let mut sidecars = vec![];
   268→    for column_index in 0..P::NumberOfColumns::USIZE {
   269→        let column = ContiguousList::try_from_iter(
   270→            (0..blob_count)
   271→                .map(|row_index| cells_and_kzg_proofs[row_index].0[column_index].clone()),
   272→        )?;
   273→        let kzg_proofs = ContiguousList::try_from_iter(
   274→            (0..blob_count).map(|row_index| cells_and_kzg_proofs[row_index].1[column_index]),
   275→        )?;
   276→
   277→        sidecars.push(
   278→            DataColumnSidecar {
   279→                index: ColumnIndex::try_from(column_index)?,
   280→                column,
   281→                kzg_commitments: kzg_commitments.clone(),
   282→                kzg_proofs,
   283→                signed_block_header,
   284→                kzg_commitments_inclusion_proof,
   285→            }
   286→            .into(),
   287→        );
   288→    }
   289→
   290→    Ok(sidecars)
   291→}
   292→
   293→pub fn construct_data_column_sidecars<P: Preset>(
   294→    signed_block: &SignedBeaconBlock<P>,
   295→    cells_and_kzg_proofs: &[CellsAndKzgProofs<P>],
   296→) -> Result<Vec<Arc<DataColumnSidecar<P>>>> {
   297→    let signed_block_header = signed_block.to_header();
   298→    let Some(post_electra_beacon_block_body) = signed_block.message().body().post_electra() else {
   299→        return Ok(vec![]);
   300→    };
   301→
   302→    let kzg_commitments = post_electra_beacon_block_body.blob_kzg_commitments();
   303→    if kzg_commitments.is_empty() {
   304→        return Ok(vec![]);
   305→    }
   306→
   307→    let kzg_commitments_inclusion_proof =
   308→        misc::kzg_commitments_inclusion_proof(post_electra_beacon_block_body);
   309→
   310→    get_data_column_sidecars(
   311→        signed_block_header,
   312→        kzg_commitments,
   313→        kzg_commitments_inclusion_proof,
   314→        cells_and_kzg_proofs,
   315→    )
   316→}
   317→
   318→pub fn construct_data_column_sidecars_from_sidecar<P: Preset>(
   319→    data_column_sidecar: &DataColumnSidecar<P>,
   320→    cells_and_kzg_proofs: &[CellsAndKzgProofs<P>],
   321→) -> Result<Vec<Arc<DataColumnSidecar<P>>>> {
   322→    let DataColumnSidecar {
   323→        kzg_commitments,
   324→        signed_block_header,
   325→        kzg_commitments_inclusion_proof,
   326→        ..
   327→    } = data_column_sidecar;
   328→
   329→    get_data_column_sidecars(
   330→        *signed_block_header,
   331→        kzg_commitments,
   332→        *kzg_commitments_inclusion_proof,
   333→        cells_and_kzg_proofs,
   334→    )
   335→}
   336→
   337→pub fn try_convert_to_cells_and_kzg_proofs<P: Preset>(
   338→    blobs: &[Blob<P>],
   339→    cell_proofs: &[KzgProof],
   340→    backend: KzgBackend,
   341→) -> Result<Vec<CellsAndKzgProofs<P>>> {
   342→    let expected_proofs_length = blobs.len() * P::CellsPerExtBlob::USIZE;
   343→    ensure!(
   344→        cell_proofs.len() == expected_proofs_length,
   345→        Error::InvalidCellsProofsLength {
   346→            expected: expected_proofs_length,
   347→            proofs_length: cell_proofs.len(),
   348→        }
   349→    );
   350→
   351→    blobs
   352→        .par_iter()
   353→        .enumerate()
   354→        .map(|(i, blob)| {
   355→            compute_cells::<P>(blob, backend).and_then(|cells| {
   356→                let start = P::CellsPerExtBlob::USIZE.saturating_mul(i);
   357→                let end = P::CellsPerExtBlob::USIZE.saturating_add(start);
   358→                ContiguousVector::try_from_iter(cell_proofs[start..end].iter().copied())
   359→                    .map(|proofs| (cells, proofs))
   360→                    .map_err(Into::into)
   361→            })
   362→        })
   363→        .collect::<Result<Vec<_>>>()
   364→}
   365→
   366→pub fn construct_cells_and_kzg_proofs<P: Preset>(
   367→    full_matrix: Vec<MatrixEntry<P>>,
   368→) -> Result<Vec<CellsAndKzgProofs<P>>> {
   369→    // Group and sort the matrix entries by blob index
   370→    let mut full_matrix_map = BTreeMap::new();
   371→    for matrix in full_matrix {
   372→        full_matrix_map
   373→            .entry(matrix.row_index)
   374→            .or_insert(Vec::new())
   375→            .push(matrix);
   376→    }
   377→
   378→    let mut result = Vec::new();
   379→    for entries in full_matrix_map.into_values() {
   380→        let (cells, proofs): (Vec<_>, Vec<_>) =
   381→            entries.into_iter().map(|e| (e.cell, e.kzg_proof)).unzip();
   382→
   383→        let cells = ContiguousVector::try_from_iter(cells.into_iter())?;
   384→        let proofs = ContiguousVector::try_from_iter(proofs.into_iter())?;
   385→        result.push((cells, proofs));
   386→    }
   387→
   388→    Ok(result)
   389→}
